def double(x):
    return x * 2
result = double(7) + 1

def area(width, height):
    return width * height
result = area(3, 4) - 2

def greet(name, punctuation="!"):
    return "Hi " + name + punctuation
result = greet("Ana", punctuation="?")

def leaf_count(level):
    if level == 0:
        return 1
    return 2 * leaf_count(level - 1)
result = leaf_count(4)

def f(n):
    if n == 0: return 1
    return n * f(n - 1)

def reach_target(n):
    if n >= 20:
        return n
    return reach_target(n + 7)
result = reach_target(3)

def total_to(n):
    if n == 0:
        return 0
    return n + total_to(n - 1)
result = total_to(4)

rubric.annotated_example:
def sum_list(items):
    if not items:
        return 0
    return items[0] + sum_list(items[1:])
The empty list stops recursion, and each call receives a shorter list.

