def reverse(text):
    if len(text) <= 1:
        return text
    return reverse(text[1:]) + text[0]
result = reverse("abc")

def shipping(weight):
    if weight <= 2:
        return 5
    return 5 + (weight - 2) * 3
result = shipping(4) + shipping(1)

def nest(n):
    if n == 0:
        return 'core'
    return '[' + nest(n - 1) + ']'
result = nest(3)

def label_depth(n):
    if n < 4:
        return 'small'
    return label_depth(n // 2) + '!'
result = label_depth(20)

def lamp_state(presses):
    if presses == 0:
        return "off"
    previous = lamp_state(presses - 1)
    if previous == "off":
        return "on"
    return "off"
result = lamp_state(5)

def notify():
    print('ready')
status = notify()

def down(n):
    if n == 0:
        return 0
    return down(n - 1)
down(2)

def repeat_mark(n):
    if n == 0:
        return ''
    return '*' + repeat_mark(n - 1)
result = repeat_mark(3)

def pulse(n):
    if n <= 0:
        return 'done'
    return pulse(n - 1)

def steps(n):
    if n == 0:
        return 0
    return 1 + steps(n - 2)

def count_to(n):
    if n == 0:
        return 0
    return 1 + count_to(n - 1)
